from collections import defaultdict

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        if maxsize is None:
            maxsize = 0
        elif not maxsize >= 0:
            raise ValueError('maxsize must be non-negative')

        if not callable(func):
            raise TypeError('Expected callable, got %s' % type(func))

        cache = {}
        counter = defaultdict(int)
        access_counter = defaultdict(int)

        def access(key):
            access_counter[key] += 1

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(kwargs.items()))
            if key in counter:
                access(key)
            if key in cache:
                return cache[key]
            if len(cache) >= maxsize and maxsize != 0:
                lfu_key = min(access_counter, key=access_counter.get)
                del access_counter[lfu_key]
                del cache[lfu_key]
            result = func(*args, **kwargs)
            cache[key] = result
            counter[key] += 1
            access(key)
            return result

        def cache_info():
            return CacheInfo(hits=len(cache), misses=len(cache) + maxsize, maxsize=maxsize, currsize=len(cache))

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache.clear
        wrapper.__wrapped__ = func

        return wrapper

    return decorator

