def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self._is_valid_coord(coord):
        return

    bin_indices = self._get_bin_indices(coord)
    if bin_indices is not None:
        for index in bin_indices:
            self._update_bin(index, weight)

    return self

    def _is_valid_coord(self, coord):
        """
        Check if the coordinate is within the histogram edges.
        """
        return all(self.edges[i][0] <= coord[i] <= self.edges[i][1] for i in range(self.ndim))

    def _get_bin_indices(self, coord):
        """
        Get the bin indices for the given coordinate.
        """
        indices = []
        for i, value in enumerate(coord):
            idx = np.searchsorted(self.edges[i], value)
            if idx < len(self.edges[i]):
                indices.append(idx - 1)
        return tuple(indices)

    def _update_bin(self, index, weight):
        """
        Update the bin at the given index with the given weight.
        """
        self.values[index] += weight

