        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
        *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        -	The formatted SQL query (:class:`str` or :class:`bytes`).

        -	The set of converted out-style parameters (:class:`dict` or
            :class:`list`).
        """
        if isinstance(params, dict) and SQLParams.in_style == 'named':
            out_params = {f':{k}': v for k, v in params.items()}
        elif isinstance(params, Sequence) and SQLParams.in_style == 'ordinal':
            out_params = list(params)
        else:
            raise ValueError("Invalid parameters for the selected parameter style")

        # Replace in-style parameters with out-style parameters in SQL query
        formatted_sql = sql
        if isinstance(sql, bytes):
            encoded_params = {k.encode('utf-8'): v for k, v in out_params.items()}
            for k, v in encoded_params.items():
                formatted_sql = formatted_sql.replace(k, v, 1)
        else:
            for k, v in out_params.items():
                formatted_sql = formatted_sql.replace(k, str(v), 1)

        return formatted_sql, out_params

