def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = []
    unused_digests = digests_used.copy()

    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            for line in file:
                if 'digest=' in line:
                    digest = line.split('digest=')[1].strip()
                    if digest not in unused_digests:
                        missing_digests.append(digest)
                    else:
                        unused_digests.remove(digest)

    if missing_digests:
        raise ValueError(f"Missing digests: {missing_digests}")

    if unused_digests:
        raise ValueError(f"Unused digests: {unused_digests}")

