        self.paths = {}
        if os.path.exists(self.path):
            with open(self.path, "r") as reader:
                for line in reader:
                    logical_path, content_path = line.strip().split(" = ")
                    if logical_path not in self.paths:
                        self.paths[logical_path] = set()
                    self.paths[logical_path].add(content_path)

def get_logical_path_map(inventory: Inventory, version: str) -> Dict[str, Set[str]]:
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for logical_path, content_paths in inventory.paths.items():
        if logical_path in inventory.paths:
            logical_path_map[logical_path] = content_paths
    return logical_path_map

