def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, list):
            return [apply_absorption(item) for item in expr]
        elif isinstance(expr, tuple):
            return tuple(apply_absorption(item) for item in expr)
        elif expr == 'A & (A | B)':
            return 'A'
        elif expr == 'A | (A & B)':
            return 'A'
        elif expr == 'A & (~A | B)':
            return 'A & B'
        elif expr == 'A | (~A & B)':
            return 'A | B'
        else:
            return expr

    return apply_absorption(args)

