    # Check if the path exists
    if not os.path.exists(path):
        return "Path does not exist"

    # Check if the path is a file
    if os.path.isfile(path):
        return "file"

    # Check if the path is a directory
    if os.path.isdir(path):
        namaste_file = os.path.join(path, "0=*")
        if os.path.exists(namaste_file):
            with open(namaste_file, 'r') as f:
                content = f.read().strip()
                if content == "root":
                    return "root"
                elif content == "object":
                    return "object"
                else:
                    return "Unknown OCFL directory type"
        else:
            return "Directory exists but missing Namaste file"
    else:
        return "Invalid path type"

