import re
import datetime

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    m = re.match(r'(\d+)\s*(year|month|day|hour|minute|second)s?', frequency, re.IGNORECASE)
    if not m:
        raise ValueError("Invalid frequency format")

    number, unit = m.groups()
    number = int(number)

    if unit.lower() == 'year':
        return datetime.timedelta(days=number * 365)
    elif unit.lower() == 'month':
        return datetime.timedelta(days=number * 30)
    elif unit.lower() == 'day':
        return datetime.timedelta(days=number)
    elif unit.lower() == 'hour':
        return datetime.timedelta(hours=number)
    elif unit.lower() == 'minute':
        return datetime.timedelta(minutes=number)
    elif unit.lower() == 'second':
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError("Invalid frequency unit")

