    return parser_dict

def _resolve_include_directive(include_info):
    """Resolves the include directive in a single item_info dictionary. """
    if isinstance(include_info, str):
        include_info = {'file': include_info}
    include_file = include_info.get('file', None)
    if include_file and not os.path.exists(include_file):
        raise FileNotFoundError(f"Include file not found: {include_file}")
    if include_file:
        with open(include_file, 'r') as f:
            include_content = f.read()
        include_dict = ut.json_loads(include_content)
        include_info.update(include_dict)
        del include_info['file']
    return include_info

